local LiceCombMaker = {}
local PRODUCTS = {
    iron_lice_comb = { name = "Železni glavnik za uši", ironCost = 4, woodCost = 1, leatherCost = 1, time = 5, cost = 170, prestige = 4, happiness = 3, description = "Železni glavnik z gostimi zobmi za odstranjevanje uši." },
    bronze_lice_comb = { name = "Bronast glavnik za uši", bronzeCost = 4, ironCost = 1, woodCost = 1, leatherCost = 1, time = 7, cost = 410, prestige = 6, happiness = 3, description = "Bronast glavnik za higiensko nego." },
    silver_lice_comb = { name = "Srebrni glavnik za uši", silverCost = 4, bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 1, time = 11, cost = 990, prestige = 11, happiness = 4, description = "Srebrni glavnik za plemiško higieno." },
    gilded_lice_comb = { name = "Pozlačeni glavnik za uši", goldCost = 1, silverCost = 4, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 15, cost = 2130, prestige = 20, happiness = 5, description = "Pozlačeni glavnik za dvorno higieno." },
    jewel_set_lice_comb = { name = "Draguljasti glavnik za uši", goldCost = 2, silverCost = 4, jewelCost = 1, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 19, cost = 4600, prestige = 36, happiness = 7, description = "Draguljasti glavnik za kraljevsko higieno." },
    royal_sovereign_lice_comb = { name = "Kraljevski suvereni glavnik za uši", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 26, cost = 9800, prestige = 69, happiness = 13, description = "Suvereni glavnik z biseri za krono." },
}
local BUILDINGS = {
    licecomb_workshop = { name = "Ušesna delavnica", cost = { gold = 340, wood = 175, stone = 135, iron = 10 }, upkeep = 6, qualityBonus = 5 },
    licecomb_house = { name = "Ušesna hiša", cost = { gold = 1220, wood = 360, stone = 270, silver = 7, iron = 8 }, upkeep = 26, qualityBonus = 18 },
    master_licecomb_atelier = { name = "Mojstrski ušesni atelje", cost = { gold = 3050, wood = 420, stone = 520, silver = 36, gold = 7 }, upkeep = 72, qualityBonus = 30 },
    sovereign_licecomb_palace = { name = "Suverena ušesna palača", cost = { gold = 13100, wood = 645, stone = 835, gold = 84, jewel = 19 }, upkeep = 257, qualityBonus = 55, prestigeBonus = 50 },
}
LiceCombMaker.ironStock = 16; LiceCombMaker.bronzeStock = 14; LiceCombMaker.woodStock = 10; LiceCombMaker.leatherStock = 8; LiceCombMaker.silverStock = 8; LiceCombMaker.goldStock = 6; LiceCombMaker.jewelStock = 4; LiceCombMaker.pearlStock = 4
LiceCombMaker.productStock = {}; LiceCombMaker.buildings = {}; LiceCombMaker.maker = nil; LiceCombMaker.activeMaking = {}; LiceCombMaker.totalProducts = 0; LiceCombMaker.dayTimer = 0
function LiceCombMaker.init() LiceCombMaker.ironStock=16; LiceCombMaker.bronzeStock=14; LiceCombMaker.woodStock=10; LiceCombMaker.leatherStock=8; LiceCombMaker.silverStock=8; LiceCombMaker.goldStock=6; LiceCombMaker.jewelStock=4; LiceCombMaker.pearlStock=4; LiceCombMaker.productStock={}; LiceCombMaker.buildings={}; LiceCombMaker.maker=nil; LiceCombMaker.activeMaking={}; LiceCombMaker.totalProducts=0; LiceCombMaker.dayTimer=0; print("[LiceCombMaker] Royal Lice Comb Maker System initialized (6 products, 4 buildings)") end
function LiceCombMaker.hireMaker(n,s) s=s or math.random(55,90); local c=590+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; LiceCombMaker.maker={name=n or ("Ušesar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ušesar najet: %s (spretnost: %d)",LiceCombMaker.maker.name,s),"success") end; return true end
function LiceCombMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function LiceCombMaker.build(id) local ok,e=LiceCombMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(LiceCombMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function LiceCombMaker.getQualityBonus() local b=0; for _,bd in ipairs(LiceCombMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function LiceCombMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and LiceCombMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and LiceCombMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and LiceCombMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and LiceCombMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and LiceCombMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and LiceCombMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and LiceCombMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and LiceCombMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #LiceCombMaker.buildings==0 then return false,"Potrebna ušesna delavnica" end; if not LiceCombMaker.maker then return false,"Potreben ušesar" end; return true end
function LiceCombMaker.make(pt,qty) qty=qty or 1; local ok,e=LiceCombMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then LiceCombMaker.ironStock=LiceCombMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then LiceCombMaker.bronzeStock=LiceCombMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then LiceCombMaker.woodStock=LiceCombMaker.woodStock-d.woodCost*qty end; if d.leatherCost then LiceCombMaker.leatherStock=LiceCombMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then LiceCombMaker.silverStock=LiceCombMaker.silverStock-d.silverCost*qty end; if d.goldCost then LiceCombMaker.goldStock=LiceCombMaker.goldStock-d.goldCost*qty end; if d.jewelCost then LiceCombMaker.jewelStock=LiceCombMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then LiceCombMaker.pearlStock=LiceCombMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if LiceCombMaker.maker then t=math.max(1,t-math.floor(LiceCombMaker.maker.skill/13)) end; table.insert(LiceCombMaker.activeMaking,{id="licecomb_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function LiceCombMaker.completeMaking(m) local q=1.0+(LiceCombMaker.getQualityBonus()/100); if LiceCombMaker.maker then q=q+(LiceCombMaker.maker.skill/140) end; q=math.min(2.5,q); LiceCombMaker.productStock[m.productType]=(LiceCombMaker.productStock[m.productType] or 0)+m.quantity; LiceCombMaker.totalProducts=LiceCombMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if LiceCombMaker.maker then LiceCombMaker.maker.itemsMade=LiceCombMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then LiceCombMaker.maker.skill=math.min(100,LiceCombMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ušesni glavnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"licecomb.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function LiceCombMaker.update(dt) if not _G.state then return end; LiceCombMaker.dayTimer=LiceCombMaker.dayTimer+dt; if LiceCombMaker.dayTimer>=30 then LiceCombMaker.dayTimer=0; for i=#LiceCombMaker.activeMaking,1,-1 do local m=LiceCombMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then LiceCombMaker.completeMaking(m); table.remove(LiceCombMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(LiceCombMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if LiceCombMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function LiceCombMaker.getStats() return {ironStock=LiceCombMaker.ironStock,bronzeStock=LiceCombMaker.bronzeStock,woodStock=LiceCombMaker.woodStock,leatherStock=LiceCombMaker.leatherStock,silverStock=LiceCombMaker.silverStock,goldStock=LiceCombMaker.goldStock,jewelStock=LiceCombMaker.jewelStock,pearlStock=LiceCombMaker.pearlStock,productStock=LiceCombMaker.productStock,numBuildings=#LiceCombMaker.buildings,hasMaker=LiceCombMaker.maker~=nil,makerName=LiceCombMaker.maker and LiceCombMaker.maker.name or "—",makerSkill=LiceCombMaker.maker and LiceCombMaker.maker.skill or 0,activeMaking=#LiceCombMaker.activeMaking,totalProducts=LiceCombMaker.totalProducts} end
return LiceCombMaker
